"""Money helpers.

A Decimal-based ``Money`` value type used everywhere on the money path.
All amounts are quantized to two decimal places using ROUND_HALF_UP as soon
as they become a ``Money`` instance, so callers never have to remember to
round themselves.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP

TWO_PLACES = Decimal("0.01")


def quantize(amount: Decimal) -> Decimal:
    """Round a Decimal to two places using ROUND_HALF_UP."""
    if not isinstance(amount, Decimal):
        raise TypeError("quantize() requires a Decimal")
    return amount.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")
        object.__setattr__(self, "amount", quantize(self.amount))

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount - other.amount, self.currency)

    def __mul__(self, multiplier: Decimal | int) -> "Money":
        if not isinstance(multiplier, (Decimal, int)):
            raise TypeError("Money can only be multiplied by Decimal or int")
        return Money(self.amount * Decimal(multiplier), self.currency)

    __rmul__ = __mul__

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"

