"""Discount rules operating on Decimal amounts (money path safe)."""

from __future__ import annotations

from decimal import Decimal

from .money import quantize

HUNDRED = Decimal("100")
ONE = Decimal("1")
ZERO = Decimal("0")


def percentage_off(amount: Decimal, percent: Decimal) -> Decimal:
    factor = ONE - Decimal(percent) / HUNDRED
    return quantize(amount * factor)


def flat_off(amount: Decimal, discount: Decimal) -> Decimal:
    result = amount - Decimal(discount)
    if result < ZERO:
        result = ZERO
    return quantize(result)


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity.

    This is a plain percentage (not a monetary amount), so it stays a float
    for backwards compatibility with existing callers/tests.
    """
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

